namespace Gojo.Experiments.QualitativeFrieze;

public static partial class StructuralEvidenceExperiment
{
    private static string Html(string data) => """
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Beyond rectangles · Gojo structural inquiry</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#eeeee2;color:#27454a;font:16px/1.6 system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:35px 25px 70px}header{max-width:1120px}h1,h2{font-family:Georgia,serif;font-weight:400;line-height:1.2}h1{font-size:clamp(34px,4vw,52px);margin:12px 0 20px}h2{font-size:30px}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.13em;color:#a96640;font-weight:700}.lede{font-size:19px}a{color:#246a70;text-underline-offset:3px}.nav{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.nav a{padding:6px 13px;border:1px solid #d5d5c6;border-radius:20px;background:#fbf8ef;text-decoration:none;font-size:14px}.note,.legend{background:#e1e6d9;border-left:3px solid #849465;padding:15px 20px;margin:24px 0}.legend{background:#e8e5f0;border-color:#805b91}.dot{display:inline-block;width:10px;height:10px;border-radius:50%;background:#b76b45}.hollow{display:inline-block;width:11px;height:11px;border:2px solid #718780;border-radius:50%}.separate{display:inline-block;color:#805b91;font-weight:bold;letter-spacing:-5px;margin-right:5px}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:9px 12px;border-bottom:1px solid #d5d5c6;text-align:left;vertical-align:top}th{font-weight:650}section{margin:35px 0}.case{background:#fbf8ef;border:1px solid #d5d5c6;padding:24px;margin:35px 0;scroll-margin-top:20px}.meta{font-size:14px;color:#617269}.context{padding:10px 15px;background:#efeddf;border-left:3px solid #a8a580}.controls{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:18px 0}select,button{font:inherit;color:inherit;border:1px solid #bac8bd;background:#fbf8ef;border-radius:5px;padding:7px 12px}button{cursor:pointer;font-size:14px}button.current{background:#28616a;color:white;border-color:#28616a}.stages{display:flex;gap:7px;flex-wrap:wrap}.evidence{padding:14px 18px;background:#e8edef;border-left:3px solid #718780;margin:18px 0;min-height:95px}.evidence strong{display:block}.evidence.open{background:#f2e8d7;border-color:#b9803f}.candidates{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.candidates.four{grid-template-columns:repeat(4,minmax(0,1fr))}.candidate{border:2px solid #d5d5c6;padding:14px;min-width:0;background:#fbf8ef;transition:border-color .15s}.candidate h3{font-size:16px;line-height:1.4;margin:0 0 8px;min-height:44px}.candidate img{width:100%;height:auto;display:block}.candidate.kept{border-color:#8198a0;background:#f0f2ef}.candidate.resolved{border-color:#638068;background:#e6eddf}.candidate.uncertain{border-color:#b9803f;background:#f3ead9}.candidate-answer{font-size:14px;font-weight:650;margin:12px 0 6px}.candidate.rejected{border-color:#bd8d83;background:#f3e9e2}.candidate.rejected img{opacity:.45}.candidate.blocked{border-style:dashed;border-color:#b9803f}.badge{font-size:13px;line-height:1.4;margin:10px 0 3px}.source{display:grid;grid-template-columns:minmax(180px,420px) 1fr;gap:20px;align-items:center}.source img{width:100%;height:auto}.status{padding:12px 15px;border-left:3px solid #8198a0;background:#e8edef;margin:18px 0}.status.resolved{border-color:#638068;background:#e6eddf}.status.open{background:#f1e6d5;border-color:#b9803f}details{border-top:1px solid #d5d5c6;padding:13px 0;margin-top:16px}summary{cursor:pointer;font-size:14px}.small{font-size:14px}.footer{font-size:14px;border-top:1px solid #d5d5c6;margin-top:30px;padding-top:20px}.control-case{border-left:4px solid #b9803f}@media(max-width:1100px){.candidates.four{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:750px){main{padding:25px 14px}.case{padding:17px}.candidates,.candidates.four{grid-template-columns:1fr}.source{grid-template-columns:1fr}.candidate img{max-height:230px;object-fit:contain}.candidate h3{min-height:0}th,td{padding:8px}}
</style></head><body><main><header><span class="eyebrow">Gojo · beyond span changes</span><h1>Which structure is possible?<br>Which question would distinguish it?</h1><p class="lede">Six small cases replace square-to-rectangle changes with closure, actual joins, headings and continuity. An unchanged policy learned on span evidence chooses questions about these new structures.</p><nav class="nav"><a href="diagnostics.json">All captured results</a><a href="inquiries.gojo.json.gz">Native inquiries and private audit archive</a><a href="../evidence-selection/gallery.html">Earlier span-selection study</a><a href="../equivalence-revision/gallery.html">Earlier expectation revisions</a></nav></header>
<div class="note"><strong>How to read this experiment</strong><ol><li>The receiver starts with a small library of possible constructions. These pictures show those alternatives, not a sequence of shape morphs.</li><li>It asks a supplier one structural question. The supplier publishes <em>yes</em>, <em>no</em> or <em>open</em> with a scoped witness.</li><li>A candidate remains possible when its answer agrees with the source reply. Both may answer <em>No</em>. A separate private evaluator later checks the remaining alternatives.</li></ol><p>This is closer to twenty questions than general shape recognition. A useful outcome can be one supported construction, several unresolved interpretations, or a visible conflict.</p><p><strong>Answer and survival are separate:</strong> source says <b>No</b> + candidate says <b>No</b> means <em>still possible</em>. Neutral cards remain possible; red cards are ruled out; green marks one remaining candidate. Green never means the candidate answered yes.</p><p><strong>Closed loop (cycle):</strong> following its connected edges returns to the starting site. A triangle is a closed three-edge loop. The open three-sided square fragment is a path with two free ends.</p></div>
<div class="legend"><strong>Diagram legend:</strong> <span class="dot"></span> shared native site · <span class="hollow"></span> free endpoint · <span class="separate">○○</span> separate identities at one displayed position · dashed purple circle: a declared nonjoining crossing, with over/under unspecified.<p class="small">All coordinates and proportions are illustrative. In particular, overlapping screen locations do not create a joint. The receiver reads native relations, not these SVGs.</p></div>
<section><h2>Unchanged policy, different kinds of evidence</h2><p>The five coefficients are reproduced from the earlier 48 span-training episodes. There is no structural retraining here. Each policy receives the same alternatives and questions.</p><div class="table-wrap"><table><thead><tr><th>Question strategy</th><th>Uniquely resolved / 6</th><th>Open / 6</th><th>Mean requests</th></tr></thead><tbody id="summary"></tbody></table></div><p class="small">One open case is expected: the same square topology has two different recipes. The fixed strategy deliberately asks an unhelpful broader check first in the other five cases: every candidate gives the same answer, so that check rules out none. This is a comparison baseline; the disagreement and transferred strategies skip it. These six authored cases are mechanics checks, not a statistical recognition benchmark.</p></section>
<section><h2>Inspect the alternatives and replies</h2><p>Use the numbered stages to compare before and after evidence. Switch strategy to inspect which question it asked first. The private source is collapsed beneath each case.</p><div id="cases"></div></section>
<section><h2>Three ways a question can remain unsettled</h2><div id="controls"></div></section>
<details><summary>What this establishes, and what it does not</summary><ul id="limits"></ul></details><footer class="footer"><p id="native"></p><p>Source-side motif induction is currently eager. This run tests selective communication and hypothesis filtering; it does not yet demonstrate avoided source-side computation.</p></footer>
<script id="data" type="application/json">__DATA__</script><script>
'use strict';const model=JSON.parse(document.querySelector('#data').textContent),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={fixed:'Fixed question order',random:'Seeded random',disagreement:'Candidate disagreement',transferred:'Transferred span-trained policy'};
document.querySelector('#summary').innerHTML=model.summaries.map(s=>`<tr><td>${esc(names[s.policy])}</td><td>${s.resolved}</td><td>${s.open}</td><td>${s.meanRequests.toFixed(2)}</td></tr>`).join('');
function article(example,control=null){const runs=model.episodes.filter(e=>e.caseId===example.id&&e.control===control),node=document.createElement('article');node.className='case'+(control?' control-case':'');node.dataset.case=example.id;if(control)node.dataset.control=control;
const controlTitles={unsearched:'Search budget exhausted',conflict:'Two reports contradict each other',incapable:'No admitted output capability'};
node.innerHTML=`<h2>${esc(control?controlTitles[control]:example.id+' · '+example.name)}</h2><p>${esc(example.description)}</p><p class="context"><strong>What matters:</strong> ${esc(example.questionPurpose)}<br><span class="small">Human reading cue: ${esc(example.humanReading)} This cue explains the example; it is not an extra native message to the receiver.</span></p><div class="controls"><label>Strategy <select aria-label="Question strategy for ${esc(example.id)}">${runs.map(e=>`<option value="${esc(e.id)}">${esc(names[e.policy])}</option>`).join('')}</select></label><span class="meta">Choose a stage below</span></div><div class="stages"></div><div class="evidence" aria-live="polite"></div><div class="candidates ${example.candidates.length===4?'four':''}">${example.candidates.map(c=>`<div class="candidate" data-candidate="${c.index}"><h3>${c.index+1}. ${esc(c.name)}</h3><a href="${esc(c.image)}"><img src="${esc(c.image)}" alt="${esc(c.name)}"></a><p class="candidate-answer"></p><p class="badge"></p></div>`).join('')}</div><div class="status"></div><details class="source-details"><summary>Reveal the private source and independent evaluation</summary><div class="source"><img src="${esc(example.sourceImage)}" alt="Private source: ${esc(example.sourceName)}"><p><strong>Source:</strong> ${esc(example.sourceName)}<br>The receiver never receives this complete source image or its generating program. This panel is for inspection after the run.</p></div><div class="evaluation"></div></details>`;
const select=node.querySelector('select');select.value=(runs.find(e=>e.policy==='transferred')||runs[0]).id;let stageIndex=0;
function show(index){const run=runs.find(e=>e.id===select.value),stage=run.stages[index];stageIndex=index;node.dataset.episode=run.id;node.dataset.stage=String(index);
node.querySelector('.stages').innerHTML=run.stages.map((s,i)=>`<button class="${i===index?'current':''}" data-step="${i}" aria-pressed="${i===index}">${esc(s.name)}</button>`).join('');node.querySelectorAll('[data-step]').forEach(button=>button.onclick=()=>show(Number(button.dataset.step)));
const evidence=node.querySelector('.evidence');evidence.classList.toggle('open',stage.answer==='Open'||stage.conflicts>0);
const sameCount=index>0&&stage.eligible.length===run.stages[index-1].eligible.length;
const allAgree=index>0&&stage.answer!=='Open'&&run.stages[index-1].eligible.every(i=>stage.reads.find(r=>r.index===i).answerToQuestion===stage.answer);
const effect=sameCount?(allAgree?` All ${stage.eligible.length} remaining candidates also answer ${esc(stage.answer)}. No alternatives were ruled out; this question cannot distinguish them.`:' No alternatives were ruled out by this reply; some evidence is still open.'):'';
evidence.innerHTML=index===0?'<strong>Start of this experiment: no source replies yet.</strong>The receiver has the candidate library and question ports, but has not asked the hidden source anything. This is the actual baseline for the run, not a future placeholder. All admitted alternatives await source evidence.':`<strong>Question sent to the hidden source: ${esc(stage.question)}</strong>Source reply: <b>${esc(stage.answer)}</b> · ${stage.eligible.length} candidates still possible.${effect}${stage.conflicts?` ${stage.conflicts} conflict witness retained.`:''}`;
for(const card of node.querySelectorAll('[data-candidate]')){
const i=Number(card.dataset.candidate),read=stage.reads.find(r=>r.index===i),kept=stage.eligible.includes(i),resolved=index>0&&kept&&stage.eligible.length===1&&read.open===0&&read.blocked===0;
card.classList.toggle('kept',kept&&index>0);card.classList.toggle('resolved',resolved);card.classList.toggle('uncertain',kept&&read.open>0);card.classList.toggle('rejected',!kept);card.classList.toggle('blocked',read.blocked>0);
card.querySelector('.candidate-answer').textContent=index===0?'Not asked yet':`This candidate answers: ${read.answerToQuestion}`;
card.querySelector('.badge').textContent=read.blocked>0?'Blocked · capability or conflict remains visible':index===0?'Not yet tested · admitted alternative':!kept?'Ruled out · disagrees with a source reply':read.open>0?'Still possible · some evidence remains open':resolved?'Still possible · only remaining candidate':'Still possible · agrees with the source replies';
}
const status=node.querySelector('.status'),atEnd=index===run.stages.length-1;status.textContent=atEnd?run.status:`After this stage: ${stage.eligible.length} alternatives remain. Continue to inspect later evidence.`;status.classList.toggle('resolved',atEnd&&run.correctAtVocabulary);status.classList.toggle('open',atEnd&&!run.correctAtVocabulary);
node.querySelector('.evaluation').innerHTML=`<p class="small">Independent evaluation tests both complete bounded motif inventories. It does not establish exact geometry, multiplicity, global arrangement or ancestry.</p><div class="table-wrap"><table><thead><tr><th>Candidate</th><th>Vocabulary agreement</th><th>Opposed claims</th><th>Open</th></tr></thead><tbody>${run.evaluations.map(e=>`<tr><td>${esc(example.candidates[e.index].name)}</td><td>${e.compatible?'Agrees':'Does not certify'}</td><td>${e.refuted}</td><td>${e.open}</td></tr>`).join('')}</tbody></table></div>`;
}select.onchange=()=>{const run=runs.find(e=>e.id===select.value);show(Math.min(stageIndex,run.stages.length-1));};show((runs.find(e=>e.id===select.value)).stages.length-1);return node;}
for(const example of model.cases)document.querySelector('#cases').append(article(example));for(const control of ['unsearched','conflict','incapable']){const run=model.episodes.find(e=>e.control===control);document.querySelector('#controls').append(article(model.cases.find(c=>c.id===run.caseId),control));}
document.querySelector('#limits').innerHTML=model.limits.map(s=>`<li>${esc(s)}</li>`).join('');document.querySelector('#native').textContent=`${model.cases.length} cases · ${model.episodes.length} episodes · ${model.nativeElements.toLocaleString()} retained native participants · ${model.nativeNumericElements} measured numeric participants · native archive restoration verified.`;const requested=new URLSearchParams(location.search).get('case');if(requested)document.querySelector(`[data-case="${CSS.escape(requested)}"]`)?.scrollIntoView();
</script></main></body></html>
""".Replace("__DATA__", data);
